using System.Globalization;
using System.Net;

namespace OJTMISApi.Services
{
    /// <summary>
    /// A file attached to an outgoing email. Mailtrap expects the bytes as
    /// base64 plus the MIME type, so PDFs generated by the API can be attached directly.
    /// </summary>
    public sealed class EmailAttachment
    {
        public string FileName { get; init; } = string.Empty;

        public byte[] Content { get; init; } = Array.Empty<byte>();

        /// <summary>MIME type. When omitted it is derived from the file name.</summary>
        public string? ContentType { get; init; }

        /// <summary>Reads a file from disk (for example a generated PDF) into an attachment.</summary>
        public static async Task<EmailAttachment> FromFileAsync(
            string path,
            CancellationToken cancellationToken = default)
        {
            ArgumentException.ThrowIfNullOrWhiteSpace(path);

            var content = await File.ReadAllBytesAsync(path, cancellationToken);
            return new EmailAttachment
            {
                FileName = Path.GetFileName(path),
                Content = content
            };
        }
    }

    /// <summary>
    /// Provider-independent description of an email. HtmlBody is sent as the
    /// rich version and TextBody as the plain-text fallback.
    /// </summary>
    public sealed class EmailRequest
    {
        public List<string> To { get; init; } = new();

        public List<string> Cc { get; init; } = new();

        public List<string> Bcc { get; init; } = new();

        public string? ReplyTo { get; init; }

        public string Subject { get; init; } = string.Empty;

        public string? HtmlBody { get; init; }

        public string? TextBody { get; init; }

        /// <summary>Mailtrap category, used to tell activation mail from password-reset mail.</summary>
        public string? Category { get; init; }

        public List<EmailAttachment> Attachments { get; init; } = new();

        public Dictionary<string, string>? Headers { get; init; }
    }

    /// <summary>
    /// Global email service used by the API. Mail is delivered through the
    /// Mailtrap Email API (sandbox inbox or transactional send).
    /// </summary>
    public interface IEmailService
    {
        /// <summary>Sends an arbitrary HTML/plain-text email with optional attachments.</summary>
        /// <returns>The Mailtrap message identifier, or an outbox identifier when credentials are not set.</returns>
        Task<string> SendAsync(EmailRequest message, CancellationToken cancellationToken = default);

        /// <summary>
        /// Sends a single HTML email to one recipient with an optional binary
        /// attachment (typically a generated PDF, sent base64-encoded).
        /// </summary>
        Task SendEmailAsync(
            string to,
            string subject,
            string htmlBody,
            byte[]? attachment = null,
            string? attachmentName = null,
            CancellationToken cancellationToken = default);

        /// <summary>Sends the account-creation email containing a temporary password.</summary>
        Task SendTemporaryPasswordAsync(
            string email,
            string name,
            string temporaryPassword,
            CancellationToken cancellationToken = default);

        /// <summary>Sends the password-reset link email.</summary>
        Task SendPasswordResetLinkAsync(
            string email,
            string name,
            string token,
            CancellationToken cancellationToken = default);
    }


    /// <summary>Inline HTML templates used by the built-in account emails.</summary>
    internal static class EmailTemplates
    {
        public static string TemporaryPassword(string appBaseUrl, string name, string temporaryPassword)
        {
            var greeting = string.IsNullOrWhiteSpace(name)
                ? "Hello"
                : $"Hello {WebUtility.HtmlEncode(name)}";
            var signIn = WebUtility.HtmlEncode($"{appBaseUrl}/login.html");
            var password = WebUtility.HtmlEncode(temporaryPassword);

            var content = $"""
                <p style="margin:0 0 16px">{greeting},</p>
                <p style="margin:0 0 16px">Your OJT-MIS account is ready. Use the temporary password below to activate it and sign in.</p>
                <p style="margin:0 0 24px">
                  <a href="{signIn}" style="display:inline-block;background:#2563eb;color:#ffffff;text-decoration:none;padding:12px 20px;border-radius:6px;font-weight:600">Sign in to OJT-MIS</a>
                </p>
                <p style="margin:0 0 8px;color:#6b7280;font-size:13px;text-transform:uppercase;letter-spacing:.04em">Temporary password</p>
                <p style="margin:0 0 24px;padding:12px 16px;background:#f3f4f6;border-radius:6px;font-family:Consolas,Menlo,monospace;font-size:16px">{password}</p>
                <p style="margin:0;color:#4b5563">After you sign in, change this password from Account &gt; Security.</p>
                """;

            return Layout("Activate your OJT-MIS account", content);
        }

        public static string PasswordReset(string name, string resetLink)
        {
            var greeting = string.IsNullOrWhiteSpace(name)
                ? "Hello"
                : $"Hello {WebUtility.HtmlEncode(name)}";
            var link = WebUtility.HtmlEncode(resetLink);

            var content = $"""
                <p style="margin:0 0 16px">{greeting},</p>
                <p style="margin:0 0 24px">A security request was made to reset the password for your OJT-MIS account.</p>
                <p style="margin:0 0 24px">
                  <a href="{link}" style="display:inline-block;background:#2563eb;color:#ffffff;text-decoration:none;padding:12px 20px;border-radius:6px;font-weight:600">Reset your password</a>
                </p>
                <p style="margin:0;color:#4b5563">If you did not request this, you can ignore this message. The link expires with the reset token.</p>
                """;

            return Layout("Reset your OJT-MIS password", content);
        }

        /// <summary>
        /// Builds the Certificate of Completion email from the values that were
        /// actually placed on the certificate (intern name, hours, office,
        /// school, OJT period, issuance date, and signatory), all pulled from
        /// the intern's record and the finalized issuance details.
        /// </summary>
        public static string CertificateOfCompletion(CertificatePdfModel certificate, string recipientName)
        {
            var greeting = string.IsNullOrWhiteSpace(recipientName)
                ? "Hello"
                : $"Hello {WebUtility.HtmlEncode(recipientName)}";

            var name = WebUtility.HtmlEncode(certificate.FullName);
            var hours = WebUtility.HtmlEncode(CertificatePdf.FormatHours(certificate.HoursRendered));
            var required = WebUtility.HtmlEncode(CertificatePdf.FormatHours(certificate.RequiredHours));
            var school = WebUtility.HtmlEncode(certificate.School);
            var office = WebUtility.HtmlEncode(certificate.Office);
            var signatory = WebUtility.HtmlEncode(certificate.SignatoryName);
            var signatoryPosition = WebUtility.HtmlEncode(certificate.SignatoryPosition);

            var period = FormatPeriod(certificate.DateStarted, certificate.DateCompleted);
            var issued = certificate.DateIssued?.ToString("MMMM d, yyyy", CultureInfo.InvariantCulture) ?? "—";

            var content = $"""
                <p style="margin:0 0 16px">{greeting},</p>
                <p style="margin:0 0 16px">Congratulations! You have completed the required <strong>{required} hours</strong> of On-the-Job Training at the Commission on Audit, rendering a total of <strong>{hours} hours</strong>.</p>
                <p style="margin:0 0 16px">Your <strong>Certificate of Completion</strong> for <strong style="text-transform:uppercase">{name}</strong> is attached to this email as a PDF. You can print it for your school records and future employment requirements.</p>
                <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:0 0 16px;border-collapse:collapse;font-size:14px">
                  <tr>
                    <td style="padding:8px 12px;background:#f3f4f6;border-radius:6px 0 0 0;color:#6b7280;width:40%">School</td>
                    <td style="padding:8px 12px;background:#f3f4f6;border-radius:0 6px 0 0;font-weight:600">{school}</td>
                  </tr>
                  <tr>
                    <td style="padding:8px 12px;background:#f9fafb;color:#6b7280">Office / Department</td>
                    <td style="padding:8px 12px;background:#f9fafb;font-weight:600">{office}</td>
                  </tr>
                  <tr>
                    <td style="padding:8px 12px;background:#f3f4f6;color:#6b7280">OJT Period</td>
                    <td style="padding:8px 12px;background:#f3f4f6;font-weight:600">{period}</td>
                  </tr>
                  <tr>
                    <td style="padding:8px 12px;background:#f9fafb;color:#6b7280">Hours Rendered</td>
                    <td style="padding:8px 12px;background:#f9fafb;font-weight:600">{hours} of {required} hours</td>
                  </tr>
                  <tr>
                    <td style="padding:8px 12px;background:#f3f4f6;color:#6b7280">Date Issued</td>
                    <td style="padding:8px 12px;background:#f3f4f6;font-weight:600">{WebUtility.HtmlEncode(issued)}</td>
                  </tr>
                  <tr>
                    <td style="padding:8px 12px;background:#f9fafb;color:#6b7280;border-radius:0 0 0 6px">Signed by</td>
                    <td style="padding:8px 12px;background:#f9fafb;border-radius:0 0 6px 0;font-weight:600">{signatory}{(signatoryPosition.Length > 0 ? $"<br><span style=\"font-weight:400;color:#4b5563\">{signatoryPosition}</span>" : string.Empty)}</td>
                  </tr>
                </table>
                <p style="margin:0 0 24px;color:#4b5563">Thank you for your service. We wish you the best in your next chapter.</p>
                <p style="margin:0;color:#4b5563">Human Resource Management Office<br>Commission on Audit</p>
                """;

            return Layout("Your Certificate of Completion", content);
        }

        private static string FormatPeriod(DateTime? start, DateTime? end)
        {
            var from = start?.ToString("MMMM d, yyyy", CultureInfo.InvariantCulture);
            var to = end?.ToString("MMMM d, yyyy", CultureInfo.InvariantCulture);

            return from is null && to is null
                ? "—"
                : $"{from ?? "—"} – {to ?? "—"}";
        }

        private static string Layout(string title, string content) =>
            LayoutTemplate
                .Replace("{{TITLE}}", WebUtility.HtmlEncode(title), StringComparison.Ordinal)
                .Replace("{{CONTENT}}", content, StringComparison.Ordinal);

        private const string LayoutTemplate = """
            <!DOCTYPE html>
            <html lang="en">
            <head>
              <meta charset="utf-8">
              <meta name="viewport" content="width=device-width, initial-scale=1">
              <title>{{TITLE}}</title>
            </head>
            <body style="margin:0;padding:0;background:#f9fafb;font-family:Segoe UI,Arial,sans-serif;color:#1f2937">
              <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f9fafb;padding:32px 16px">
                <tr>
                  <td align="center">
                    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border:1px solid #e5e7eb;border-radius:10px">
                      <tr>
                        <td style="padding:24px 28px;border-bottom:1px solid #e5e7eb">
                          <span style="font-size:18px;font-weight:700;color:#111827">OJTMIS</span>
                          <span style="display:block;font-size:12px;color:#6b7280">On-the-Job Training Management Information System</span>
                        </td>
                      </tr>
                      <tr>
                        <td style="padding:28px;font-size:15px;line-height:1.55">
                          {{CONTENT}}
                        </td>
                      </tr>
                      <tr>
                        <td style="padding:16px 28px;border-top:1px solid #e5e7eb;font-size:12px;color:#9ca3af">
                          This is an automated message. Please do not reply.
                        </td>
                      </tr>
                    </table>
                  </td>
                </tr>
              </table>
            </body>
            </html>
            """;
    }
}
